// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Raising insertion sort threshold to 24 in introsort reduces recursion overhead and improves avg_time
// MECHANISM-1: Fewer recursive calls for medium subarrays; insertion sort is efficient up to ~24 elements due to low overhead
// EXPECT-1: performance_score > 0.998
// RESULT-1: REFUTED (actual=0.9973102532496754)
// HYPOTHESIS-2: Checking for reverse-sorted segments and reversing them improves adaptability on reverse-sorted inputs
// MECHANISM-2: Reverse-sorted arrays cause worst-case behavior; detecting and flipping them makes performance more uniform
// EXPECT-2: adaptability_score > 0.9997
// RESULT-2: REFUTED (actual=0.9996129292041667)
// HYPOTHESIS-3: Tighter disorder threshold (len/6) catches more nearly-sorted arrays for fast-path insertion sort
// MECHANISM-3: Slightly more aggressive nearly-sorted detection reduces avg time on partially sorted data without hurting random
// EXPECT-3: combined_score > 0.999
// RESULT-3: REFUTED (actual=0.9982313236314718)

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= 32 { insertion_sort(arr); return; }
    // Check if nearly sorted or nearly reverse-sorted
    let mut disorder = 0usize;
    let mut rev_disorder = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { disorder += 1; }
        else if arr[i] < arr[i + 1] { rev_disorder += 1; }
    }
    if disorder <= len / 6 {
        insertion_sort(arr);
        return;
    }
    if rev_disorder <= len / 6 {
        arr.reverse();
        insertion_sort(arr);
        return;
    }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], depth: usize) {
    let len = arr.len();
    if len <= 24 { insertion_sort(arr); return; }
    if depth == 0 { heapsort(arr); return; }
    let pivot = partition_mo3(arr);
    let (left, right) = arr.split_at_mut(pivot);
    introsort(left, depth - 1);
    introsort(&mut right[1..], depth - 1);
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T]) -> usize {
    let len = arr.len();
    let mid = len / 2;
    let last = len - 1;
    // Median-of-three pivot selection
    if arr[0] > arr[mid] { arr.swap(0, mid); }
    if arr[0] > arr[last] { arr.swap(0, last); }
    if arr[mid] > arr[last] { arr.swap(mid, last); }
    arr.swap(mid, last - 1);
    let pivot = arr[last - 1].clone();
    let mut i = 0;
    let mut j = last - 1;
    loop {
        i += 1; while arr[i] < pivot { i += 1; }
        j -= 1; while arr[j] > pivot { j -= 1; }
        if i >= j { break; }
        arr.swap(i, j);
    }
    arr.swap(i, last - 1);
    i
}

fn heapsort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    for i in (0..len / 2).rev() { sift_down(arr, i, len); }
    for end in (1..len).rev() {
        arr.swap(0, end);
        sift_down(arr, 0, end);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    loop {
        let mut child = 2 * root + 1;
        if child >= end { break; }
        if child + 1 < end && arr[child] < arr[child + 1] { child += 1; }
        if arr[root] >= arr[child] { break; }
        arr.swap(root, child);
        root = child;
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

